const cohorts = $input.all().map(i => i.json);
if (!cohorts.length || !cohorts[0].cohort_month) return [{ json: { no_data: true } }];

const cohortAnalysis = cohorts.map(c => {
  const size = parseInt(c.cohort_size) || 1;
  return {
    month: c.cohort_month,
    size: size,
    converted: parseInt(c.converted) || 0,
    conversion_rate: Math.round((parseInt(c.converted) || 0) / size * 100),
    retention: {
      day_30: Math.round((parseInt(c.retained_30d) || 0) / size * 100),
      day_60: Math.round((parseInt(c.retained_60d) || 0) / size * 100),
      day_90: Math.round((parseInt(c.retained_90d) || 0) / size * 100)
    },
    revenue: parseFloat(c.total_revenue) || 0,
    avg_ltv: parseFloat(c.avg_ltv) || 0
  };
});

// Overall metrics
const totalLeads = cohortAnalysis.reduce((s, c) => s + c.size, 0);
const totalConverted = cohortAnalysis.reduce((s, c) => s + c.converted, 0);
const totalRevenue = cohortAnalysis.reduce((s, c) => s + c.revenue, 0);
const avgConversionRate = Math.round(totalConverted / totalLeads * 100);
const avgLTV = totalConverted > 0 ? Math.round(totalRevenue / totalConverted) : 0;

// Retention trend
const avgRetention30 = Math.round(cohortAnalysis.reduce((s, c) => s + c.retention.day_30, 0) / cohortAnalysis.length);
const avgRetention60 = Math.round(cohortAnalysis.reduce((s, c) => s + c.retention.day_60, 0) / cohortAnalysis.length);
const avgRetention90 = Math.round(cohortAnalysis.reduce((s, c) => s + c.retention.day_90, 0) / cohortAnalysis.length);

return [{
  json: {
    period: '12 months',
    summary: {
      total_leads: totalLeads,
      total_converted: totalConverted,
      avg_conversion_rate: avgConversionRate,
      total_revenue: totalRevenue,
      avg_ltv: avgLTV,
      avg_retention_30d: avgRetention30,
      avg_retention_60d: avgRetention60,
      avg_retention_90d: avgRetention90
    },
    cohorts: cohortAnalysis,
    generated_at: new Date().toISOString()
  }
}];

